// Read the trigger input; always emit exactly these two mock orders.
$input.all();
const orders = [
  {
    order_id: 'A-1001',
    created_at: '2026-10-09T10:00:00Z',
    customer_name: 'Ona Test',
    customer_email: 'ona@example.com',
    items: [
      { sku: 'MUG', qty: 2, unit_price_cents: 1250 },
      { sku: 'PEN', qty: 1, unit_price_cents: 500 }
    ]
  },
  {
    order_id: 'B-1002',
    created_at: '2026-10-09T11:00:00Z',
    customer_name: 'Bo Test',
    customer_email: '',
    items: [{ sku: 'MUG', qty: 0, unit_price_cents: 1250 }]
  }
];
return orders.map((order) => ({ json: order }));

return $input.all().map(({ json: order }) => {
  const reasons = [];
  for (const field of ['order_id', 'created_at', 'customer_name', 'customer_email']) {
    if (typeof order[field] !== 'string' || order[field].trim() === '') {
      reasons.push('missing ' + field);
    }
  }
  if (typeof order.customer_email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(order.customer_email)) {
    reasons.push('invalid customer_email');
  }
  if (!Array.isArray(order.items) || order.items.length === 0) {
    reasons.push('missing items');
  } else {
    order.items.forEach((item, i) => {
      const line = item ?? {};
      if (!Number.isInteger(line.qty) || line.qty <= 0) {
        reasons.push('items[' + i + '].qty must be a positive integer');
      }
      if (!Number.isInteger(line.unit_price_cents) || line.unit_price_cents < 0) {
        reasons.push('items[' + i + '].unit_price_cents must be a non-negative integer');
      }
    });
  }
  return { json: { ...order, valid: reasons.length === 0, reasons } };
});

return $input.all().map(({ json: order }) => {
  if (!order.valid) {
    return { json: { error: { order_id: order.order_id, reasons: order.reasons } } };
  }
  const items_count = order.items.length;
  const total_cents = order.items.reduce((sum, item) => sum + item.qty * item.unit_price_cents, 0);
  const c = total_cents;
  const total_eur = String((c - c % 100) / 100) + '.' + String(c % 100).padStart(2, '0');
  const sheet_row = {
    order_id: order.order_id,
    created_at: order.created_at,
    customer_name: order.customer_name,
    customer_email: order.customer_email,
    items_count,
    total_cents,
    total_eur
  };
  const notification = {
    to: 'ops@example.com',
    subject: 'New order ' + order.order_id,
    body: 'Order ' + order.order_id + ' from ' + order.customer_name + ': ' + items_count + ' line items, total ' + total_eur + ' EUR.'
  };
  return { json: { sheet_row, notification } };
});
